INSERT INTO public.events (id, title, description, event_date, start_time, end_time, max_capacity, venue, event_type, eligible_years, visibility, status, faculty_coordinators, student_coordinators, rules, prerequisites, participation_type)
VALUES
    ('ev_vibe_coding', 'Vibe Coding', 'Vibe Coding is a technical team-based event where participants identify a real-world problem, build a working tech solution, and present it live to a panel of judges. Teams must demonstrate a fully functional application, website, software, AI tool, or hardware project.', '2026-09-15', '09:15 AM', '10:30 AM', 60, 'IT Lab, IT Department', 'Technical', 'All', 'PUBLIC', 'OPEN', 'U. Srinadh, A. Nagajyothi', 'K. Phani Kumar, SK. Karishma', '["Each team must consist of 2–4 members only.","The project must be original and developed/presented by the participating team.","Teams must submit their GitHub repository link and deployment link on the event portal before the event — failure to do so will result in disqualification.","The repository must be public; a private/non-accessible repository will be treated as non-submission.","The deployment link must be live and accessible during the presentation. A dead link will be treated as non-submission.","Each team gets exactly 5 minutes total for presentation and live demonstration.","Teams must complete their setup within the allotted time.","Any form of plagiarism or unauthorized copying of another team''s project will lead to immediate disqualification.","Proper formal/professional dress code must be maintained by all participants.","Participants must maintain discipline and professional behavior throughout the event.","Participants must bring all electronic equipment required for their project (laptops, chargers, USB cables, microcontrollers, etc.).","The decision of the judges will be final and binding."]', '["Team of 2–4 members registered","Problem statement and proposed solution prepared","Working application / project ready and tested","Public GitHub repository link submitted with README file","Deployment / live demo link verified live and accessible","All required equipment and chargers brought to the venue","Formal/professional dress code"]', '2–4 Members per team'),
    ('ev_debugging', 'Debugging', 'Debugging is a technical competition designed to test participants'' programming, logical thinking, error-identification, and code-correction skills. Participants are given C language programs with intentional errors and must identify and fix them within the given time.', '2026-09-15', '10:45 AM', '11:45 AM', 80, 'IT Lab, IT Department', 'Technical', 'All', 'PUBLIC', 'OPEN', 'T. Vinay', 'M. Vamsi, V. Rishikesh', '["This event is strictly individual — no teams allowed.","All programs will be in C language only. No other language is permitted.","Participants must use only the computer assigned to them in the IT Lab.","Only the permitted safe browser and provided resources may be used.","Participants must not access unauthorized websites, applications, files, or external devices.","Use of mobile phones or other personal devices during the competition is strictly prohibited.","Participants must not communicate with other participants during the round.","No copying of code or solutions from another participant is allowed.","Participants must save/submit their corrected programs as instructed by the coordinators.","Participants must stop working immediately when the 15-minute time limit ends.","Any attempt to bypass competition rules will result in immediate disqualification.","The decision of the judges/coordinators will be final and binding."]', '["Individual participation (no team)","Knowledge of C language fundamentals (syntax, loops, pointers, arrays, functions)","No personal devices / mobile phones during the event","Ready to work on assigned lab computer only"]', 'Individual (No teams)'),
    ('ev_tech_quiz', 'Tech Quiz', 'Tech Quiz is an individual technical knowledge competition conducted on a dedicated online quiz platform. Participants answer technology-related questions across two rounds, testing their knowledge of computer science, programming, IT concepts, and current tech trends.', '2026-09-15', '11:55 AM', '12:50 PM', 100, 'IT Lab, IT Department', 'Technical', 'All', 'PUBLIC', 'OPEN', 'K. Rammohana Rao', 'M. Srisha, J. Likitha', '["Strictly individual — no assistance from other participants or external persons is allowed.","Participants must use only the computer/system assigned to them.","Only the provided quiz platform may be accessed during the event.","Use of mobile phones, personal devices, or external resources is strictly prohibited.","Participants must not communicate with others during either round.","Any attempt to use unfair means will result in immediate disqualification.","Participants must follow the instructions given by the coordinators at all times.","The scores displayed on the platform will be considered final for shortlisting.","The decision of the judges/coordinators will be final and binding."]', '["Individual participation (no team)","Report to the venue before the start time","No personal devices / mobile phones during the event","Knowledge of core CS/IT concepts"]', 'Individual (No teams)'),
    ('ev_idea_pitch', 'Idea Pitch', 'Idea Pitch is a technical team-based event where participants identify a real-world problem or opportunity and present a clear, well-structured idea to a panel of judges using the official organizer-provided PPT template. Each team gets a fixed slot to pitch their concept and answer questions from the judges.', '2026-09-15', '12:50 PM', '01:45 PM', 50, 'IT Lab, IT Department', 'Technical', 'All', 'PUBLIC', 'OPEN', 'Dr. AVN Chandra Sekhar, G. Nageswarao', 'K. Sarvagna, Y. Srikanth', '["Each team must consist of 2–4 members only.","The idea must be original and developed by the participating team.","All teams must use the official PPT template provided by the organizers — no custom templates allowed.","The PPT must be submitted before the event for smooth transitions between teams.","All team members must be present at the venue.","Presentations must cover: Idea Overview, Problem it Solves, Proposed Solution, Uniqueness, and Impact/Feasibility.","Strict adherence to the 3-minute pitch + 2-minute Q&A time limit is mandatory.","Any form of plagiarism or presenting another team''s idea may lead to disqualification.","Proper formal/professional dress code must be maintained.","Participants must follow the instructions given by the event coordinators and judges.","The decision of the judges will be final and binding."]', '["Team of 2–4 members registered","Idea finalized (Problem, Solution, Uniqueness, Impact)","Presentation prepared using the official PPT template only","PPT submitted before the event","All team members present at the venue","Formal/professional dress code"]', '2–4 Members per team'),
    ('ev_art_gallery', 'Art Gallery', 'Art Gallery is scheduled as part of the technical events lineup, showcasing creative artworks, sketches, digital art, paintings, and craftwork created by engineering students. Coordinated by IT department students and faculty.', '2026-09-15', '01:45 PM', '02:10 PM', 40, 'Class Room (Available)', 'Creative', 'All', 'PUBLIC', 'OPEN', 'M. Tangamani', 'Ch. Jhansi, M. Srisha', '["Open to all students of Information Technology department.","Original artwork must be submitted/displayed before the start time.","Allowed media: Pencil sketches, oil/acrylic paintings, watercolor, digital art prints, and craftwork.","Artwork must be accompanied by a title and brief creator description.","Offensive, inappropriate, or plagiarized art will not be accepted.","Participants must be present during judging to explain their concept.","The decision of the judges will be final and binding."]', '["Artwork completed and ready for exhibition","Title and concept note prepared","Report to classroom venue by 1:30 PM for setup"]', 'Individual / Duo'),
    ('ev_screened_performance', 'Screened Performance (Singing & Mime / Narrative Dance)', 'Screened Performance is a cultural event where participants submit pre-recorded videos of their singing and/or mime/narrative dance performance. There are no live performances — all entries are screened to the audience and judged by the panel. Participants may submit one or both types of entries.', '2026-09-15', '03:00 PM', '03:30 PM', 60, 'AIML Seminar Hall', 'Cultural', 'All', 'PUBLIC', 'OPEN', 'G. Saraswathi', 'Ch. Jhansi, V. Rohit', '["No live performances — only pre-recorded videos will be screened.","Maximum video duration is 2 minutes per entry. Videos exceeding 2 minutes will be trimmed.","The performance must be the participant''s own — no lip-sync only videos; instrumental-only videos not accepted for singing.","Accepted file formats: MP4 or MOV. Minimum video resolution: 720p (HD) for clear screening.","The video must have clear audio. Background music/karaoke track is allowed.","Any language is permitted (Telugu, Hindi, English, etc.).","Mime/narrative dance can be classical, folk, contemporary, or expressive dance forms.","Only one entry per category per participant (one singing + one dance/mime maximum).","Obscene, offensive, or inappropriate content is strictly prohibited.","Submissions must be made before the deadline. Late submissions will not be accepted.","The decision of the judges will be final and binding."]', '["Pre-recorded singing video (max 2 min) — if participating in singing","Pre-recorded mime/dance video (max 2 min) — if participating in dance","File in MP4 / MOV format with minimum 720p resolution and clear audio","Video submitted before deadline on the specified platform","Content is appropriate and inoffensive"]', 'Individual'),
    ('ev_meme_mania', 'Meme Mania', 'Meme Mania is a fun, individual creative event where participants submit a pre-made tech-themed meme before the event. Submitted memes are screened for the audience and judged on creativity, humour, relevance to technology, and originality.', '2026-09-19', '03:00 PM', '04:30 PM', 100, 'Screening Hall', 'Creative', 'All', 'PUBLIC', 'OPEN', 'Dr. AVN Chandra Sekhar, T. Vinay', 'V. Lohith, K. Ganapathi', '["Strictly individual — no team submissions.","Only one meme entry per participant is allowed.","The meme must be tech-themed (related to programming, IT, computers, software, engineering, or tech life). Off-topic memes will be disqualified.","The meme must be the participant''s own original creation — no copying or stealing others'' memes.","Accepted file formats: PNG, JPG, or GIF.","Explicit, hateful, offensive, or politically sensitive content is strictly prohibited and will lead to immediate disqualification.","Submissions must be made before the deadline shared by the coordinators.","Late submissions will not be accepted under any circumstances.","The decision of the judges will be final and binding."]', '["Individual participation (no team)","Tech-themed meme created (original, no copying)","File in PNG / JPG / GIF format","Submitted before deadline on specified platform","Content is appropriate and inoffensive"]', 'Individual (No teams)')
