-- Enable UUID extension
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 1. ACADEMIC YEARS
CREATE TABLE IF NOT EXISTS public.academic_years (
    id TEXT PRIMARY KEY,
    year_name TEXT NOT NULL UNIQUE,
    is_current BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. USERS (Super Admin, Staff, Students)
CREATE TABLE IF NOT EXISTS public.users (
    id TEXT PRIMARY KEY,
    username TEXT UNIQUE NOT NULL,
    email TEXT,
    password_hash TEXT DEFAULT 'MANAGED_AUTH',
    role TEXT NOT NULL CHECK (role IN ('STUDENT', 'STAFF', 'SUPER_ADMIN')),
    department TEXT NOT NULL DEFAULT 'Information Technology',
    status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'INACTIVE', 'ARCHIVED')),
    must_change_password BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 3. STUDENTS DETAIL TABLE
CREATE TABLE IF NOT EXISTS public.students (
    user_id TEXT PRIMARY KEY REFERENCES public.users(id) ON DELETE CASCADE,
    roll_no TEXT UNIQUE NOT NULL,
    name TEXT NOT NULL,
    email TEXT,
    department TEXT NOT NULL DEFAULT 'Information Technology',
    year_level TEXT NOT NULL,
    section TEXT DEFAULT 'B',
    academic_year_id TEXT REFERENCES public.academic_years(id),
    qr_token TEXT UNIQUE NOT NULL,
    status TEXT NOT NULL DEFAULT 'ACTIVE',
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 4. STAFF DETAIL TABLE
CREATE TABLE IF NOT EXISTS public.staff (
    user_id TEXT PRIMARY KEY REFERENCES public.users(id) ON DELETE CASCADE,
    employee_id TEXT UNIQUE NOT NULL,
    name TEXT NOT NULL,
    designation TEXT DEFAULT 'Assistant Professor',
    department TEXT NOT NULL DEFAULT 'Information Technology',
    email TEXT,
    phone TEXT,
    cabin TEXT DEFAULT 'IT Staff Room A',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 5. EVENTS TABLE
CREATE TABLE IF NOT EXISTS public.events (
    id TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    description TEXT NOT NULL,
    banner_url TEXT,
    event_date DATE NOT NULL DEFAULT CURRENT_DATE,
    start_time TEXT NOT NULL DEFAULT '10:00 AM',
    end_time TEXT DEFAULT '04:00 PM',
    reg_start TIMESTAMPTZ,
    reg_end TIMESTAMPTZ,
    max_capacity INTEGER NOT NULL DEFAULT 100,
    registered_count INTEGER NOT NULL DEFAULT 0,
    venue TEXT NOT NULL DEFAULT 'Campus Auditorium',
    event_type TEXT NOT NULL DEFAULT 'Technical',
    eligible_years TEXT NOT NULL DEFAULT 'All',
    visibility TEXT NOT NULL DEFAULT 'PUBLIC',
    status TEXT NOT NULL DEFAULT 'OPEN',
    platform_url TEXT,
    platform_config TEXT,
    faculty_coordinators TEXT DEFAULT 'IT Department Faculty',
    student_coordinators TEXT,
    rules TEXT,
    prerequisites TEXT,
    participation_type TEXT DEFAULT 'Individual',
    created_by TEXT REFERENCES public.users(id),
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 6. EVENT REGISTRATIONS TABLE
CREATE TABLE IF NOT EXISTS public.event_registrations (
    id TEXT PRIMARY KEY,
    event_id TEXT NOT NULL REFERENCES public.events(id) ON DELETE CASCADE,
    student_id TEXT NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
    student_roll TEXT,
    student_name TEXT,
    student_email TEXT,
    student_year TEXT,
    team_name TEXT,
    status TEXT NOT NULL DEFAULT 'CONFIRMED',
    registered_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(event_id, student_id)
);

-- 7. EVENT STAFF ASSIGNMENTS
CREATE TABLE IF NOT EXISTS public.event_staff (
    id TEXT PRIMARY KEY,
    event_id TEXT NOT NULL REFERENCES public.events(id) ON DELETE CASCADE,
    staff_id TEXT NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
    assigned_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(event_id, staff_id)
);

-- 8. EVENT ATTENDANCE TABLE (Turnstile & QR Verification)
CREATE TABLE IF NOT EXISTS public.event_attendance (
    id TEXT PRIMARY KEY,
    event_id TEXT NOT NULL,
    student_id TEXT NOT NULL,
    student_roll TEXT,
    student_name TEXT,
    student_email TEXT,
    scanned_by TEXT NOT NULL DEFAULT 'Turnstile Gate #2',
    scanned_by_name TEXT DEFAULT 'Turnstile Scanner',
    status TEXT NOT NULL DEFAULT 'PRESENT',
    session TEXT NOT NULL DEFAULT 'DEFAULT',
    scanned_at TIMESTAMPTZ DEFAULT NOW()
);

-- 9. POLLS TABLE
CREATE TABLE IF NOT EXISTS public.polls (
    id TEXT PRIMARY KEY,
    question TEXT NOT NULL,
    description TEXT,
    category TEXT DEFAULT 'Department',
    target_years TEXT DEFAULT 'All',
    status TEXT NOT NULL DEFAULT 'OPEN',
    winner_option_id TEXT,
    created_by TEXT REFERENCES public.users(id),
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 10. POLL OPTIONS TABLE
CREATE TABLE IF NOT EXISTS public.poll_options (
    id TEXT PRIMARY KEY,
    poll_id TEXT NOT NULL REFERENCES public.polls(id) ON DELETE CASCADE,
    text TEXT NOT NULL,
    vote_count INTEGER NOT NULL DEFAULT 0
);

-- 11. POLL VOTES TABLE
CREATE TABLE IF NOT EXISTS public.poll_votes (
    id TEXT PRIMARY KEY,
    poll_id TEXT NOT NULL REFERENCES public.polls(id) ON DELETE CASCADE,
    option_id TEXT NOT NULL REFERENCES public.poll_options(id) ON DELETE CASCADE,
    student_id TEXT NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
    voted_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(poll_id, student_id)
);

-- 12. NOTIFICATIONS TABLE
CREATE TABLE IF NOT EXISTS public.notifications (
    id TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    message TEXT NOT NULL,
    category TEXT DEFAULT 'Urgent',
    target_audience TEXT DEFAULT 'ALL',
    target_event_id TEXT REFERENCES public.events(id),
    sent_by TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 13. NOTIFICATION READS TABLE
CREATE TABLE IF NOT EXISTS public.notification_reads (
    id TEXT PRIMARY KEY,
    notification_id TEXT NOT NULL REFERENCES public.notifications(id) ON DELETE CASCADE,
    user_id TEXT NOT NULL,
    read_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(notification_id, user_id)
);

-- 14. ALERTS TABLE
CREATE TABLE IF NOT EXISTS public.alerts (
    id TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    content TEXT NOT NULL,
    alert_type TEXT NOT NULL DEFAULT 'INFO',
    target_audience TEXT NOT NULL DEFAULT 'ALL',
    is_published BOOLEAN DEFAULT TRUE,
    expires_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 15. ANNOUNCEMENTS TABLE
CREATE TABLE IF NOT EXISTS public.announcements (
    id TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    content TEXT NOT NULL,
    image_url TEXT,
    is_published BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 16. STUDENT QUERIES (Raise Doubt / Helpdesk)
CREATE TABLE IF NOT EXISTS public.student_queries (
    id TEXT PRIMARY KEY,
    student_name TEXT NOT NULL,
    roll_no TEXT NOT NULL,
    email TEXT,
    year_level TEXT,
    category TEXT DEFAULT 'Lab Support',
    mentor TEXT DEFAULT 'IT Helpdesk',
    title TEXT NOT NULL,
    description TEXT,
    urgency TEXT DEFAULT 'Normal',
    status TEXT DEFAULT 'QUEUED',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 17. AUDIT LOGS TABLE
CREATE TABLE IF NOT EXISTS public.audit_logs (
    id TEXT PRIMARY KEY,
    user_id TEXT,
    user_name TEXT,
    user_role TEXT,
    action TEXT NOT NULL,
    target_entity TEXT NOT NULL,
    details TEXT,
    timestamp TIMESTAMPTZ DEFAULT NOW()
);

-- 18. FCM DEVICE TOKENS TABLE
CREATE TABLE IF NOT EXISTS public.fcm_tokens (
    token TEXT PRIMARY KEY,
    user_id TEXT NOT NULL,
    year_level TEXT,
    role TEXT DEFAULT 'STUDENT',
    active BOOLEAN DEFAULT TRUE,
    platform TEXT DEFAULT 'android',
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- ==============================================================================
-- ROW LEVEL SECURITY (RLS) POLICIES - FULL ANON ACCESS
-- ==============================================================================

DO $$
DECLARE
    tbl text;
BEGIN
    FOR tbl IN
        SELECT table_name FROM information_schema.tables
        WHERE table_schema = 'public'
    LOOP
        EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY;', tbl);
        EXECUTE format('DROP POLICY IF EXISTS "Public select %I" ON public.%I;', tbl, tbl);
        EXECUTE format('CREATE POLICY "Public select %I" ON public.%I FOR SELECT USING (true);', tbl, tbl);
        EXECUTE format('DROP POLICY IF EXISTS "Public insert %I" ON public.%I;', tbl, tbl);
        EXECUTE format('CREATE POLICY "Public insert %I" ON public.%I FOR INSERT WITH CHECK (true);', tbl, tbl);
        EXECUTE format('DROP POLICY IF EXISTS "Public update %I" ON public.%I;', tbl, tbl);
        EXECUTE format('CREATE POLICY "Public update %I" ON public.%I FOR UPDATE USING (true);', tbl, tbl);
        EXECUTE format('DROP POLICY IF EXISTS "Public delete %I" ON public.%I;', tbl, tbl);
        EXECUTE format('CREATE POLICY "Public delete %I" ON public.%I FOR DELETE USING (true);', tbl, tbl);
    END LOOP;
END $$;

